-- 0316: REVERT 0310 exactly.
--
-- 0310 (2026-10-15) created 417 areas for climbs on catch-all lists. Its check for a place we already had matched
-- names EXACTLY within 1.5 km, so it re-created places we had under variant names and moved their climbs onto the
-- copies: Stone Fort's whole tree a second time ("Front Area", "Moss Man Area", "Jungle Gym/ Fromundathunda Area"),
-- peaks under the source's parent ("Mt. Baker" beside Mount Baker, taking 7 of its routes; Mt. Goode, Mt. Temple,
-- Amphitheatre / Amphitheater Mountain), spellings ("Chuckwalla" / "Chuckawalla Wall", "Ellesmere" / "Ellsmere
-- Island", "Reggae" / "Raggae Rock"), our labelled names ("(.3) Cougar's Den" / "Cougar's Den"). check:area-duplicates
-- saw 17; a wider read found ~60. Read pair by pair it is a redo, not a fix, so this puts 0310 back:
--   the 91 lists it deleted, re-created (same id, name, parent, pin, and every other column, from its rollback file);
--   all 2056 of its climb moves reversed; its 417 areas folded away once empty; the fill it did to keepers undone.
-- 417 areas deleted. No climb is deleted.
-- ABORTS if the live tree no longer matches the plan.
-- Plan: the job's fold21/decide.mjs, from scripts/data/boulders-created-rollback.json (0310's own rollback).

