s east of Washington Pass. It is one of the largest and cleanest roadside crags in Washington, known for bulletproof granite and a mid-height system of huge caves (the largest \"Supercave\" is roughly the size of a tennis court). Long ignored after a single 1969 aid ascent, the wall saw almost no further traffic for 40 years until Erik Lawson and Lee Arden Pete established Ellen Pea (2009), followed by a wave of hard free climbing from Blake Herrington and partners (The Tiger, 2014; free variation of the L&H Route, 2015) and Colin Moorhead/Tom Wright (Golden Age, 2016).","aspect":"S"},{"id":"wi_7_cannon_boulder","lat":43.01258,"lng":-90.12165,"coords_approx":false,"parking_lat":null,"parking_lng":null,"parking_name":null,"rock":"sandstone","rock_basis":"mapped","approach":null,"blurb":null,"aspect":null},{"id":"ca_center_crag_climbs","lat":34.09294,"lng":-116.15722,"coords_approx":false,"parking_lat":null,"parking_lng":null,"parking_name":null,"rock":"monzogranite","rock_basis":"mapped","approach":null,"blurb":null,"aspect":null},{"id":"ca_calf_implants","lat":34.48697,"lng":-117.13139,"coords_approx":false,"parking_lat":34.484184,"parking_lng":-117.131424,"parking_name":"Horsemen''s Center dirt lot to the right of the entrance","rock":"granite","rock_basis":"mapped","approach":null,"blurb":null,"aspect":null},{"id":"ca_boulder_n_aka_pimp_juice_boulder","lat":38.88064,"lng":-120.01097,"coords_approx":false,"parking_lat":null,"parking_lng":null,"parking_name":null,"rock":"granodiorite","rock_basis":"mapped","approach":null,"blurb":null,"aspect":null},{"id":"ca_thanks_obama_boulder","lat":33.21341,"lng":-116.46066,"coords_approx":false,"parking_lat":null,"parking_lng":null,"parking_name":null,"rock":"tonalite","rock_basis":"mapped","approach":null,"blurb":null,"aspect":null},{"id":"co_ed_rock","lat":38.89234,"lng":-104.90591,"coords_approx":false,"parking_lat":null,"parking_lng":null,"parking_name":null,"rock":"limestone","rock_basis":"mapped","approach":null,"blurb":